In some very rare circumstances, it is interesting to use the repetition
of options to count an integer up.  This can be used for verbosity flags,
for instance:

.. click:example::

    @click.command()
    @click.option('-v', '--verbose', count=True)
    def log(verbose):
        click.echo(f"Verbosity: {verbose}")

if option.takes_value:
    # Any characters left in arg?  Pretend they're the
    # next arg, and stop consuming characters of arg.
    if i < len(arg):
        state.rargs.insert(0, arg[i:])
        stop = True

    value = self._get_value_from_state(opt, option, state)

else:
    value = None

option.process(value, state)

if stop:
    break

if output_file.name != "-" and output_file.name in src_files:
    raise click.BadArgumentUsage(
        f"input and output filenames must not be matched: {output_file.name}"
    )
